python3 - << 'PY'
import json

# Load all defs
defs = {}
for name, f in [('ixp','/tmp/ixp_def.json'),('apiwf','/tmp/apiwf_def.json'),('agent','/tmp/agent_def.json'),('ctx','/tmp/ctx_def.json'),('end','/tmp/end_def.json'),('switch','/tmp/switch_def.json'),('merge','/tmp/merge_def.json'),('decision','/tmp/decision_def.json'),('script','/tmp/script_def.json'),('trigger','/tmp/trigger_def.json')]:
    d = json.load(open(f))
    node = d.get('Data', {}).get('Node', d.get('Data', {}))
    defs[name] = node

# Load current flow to preserve scaffold data
flow = json.load(open('/work/output/artifacts/skill-flow-devcon-billing-dispute-resolution/BillingDisputeResolution/BillingDisputeResolution/BillingDisputeResolution.flow'))

# IxP model blob from inputDefaults
ixp_defaults = defs['ixp'].get('inputDefaults', {})
ixp_model_blob = ixp_defaults.get('model', {})
# Fix modelName if null
if not ixp_model_blob.get('modelName'):
    ixp_model_blob['modelName'] = ixp_model_blob.get('modelDisplayName', 'invoices-billing')

ixp_out = defs['ixp']['outputDefinition']

# Agent 1: Dispute Analyst
ANALYST_ID = '83b5321c-d7f8-4e93-8c86-ec6fc500ba2d'
# Agent 2: Resolution Writer
WRITER_ID = '1dd7cfff-36ab-4dbf-bc17-b3ad7bc3e45d'
# Context node UUID for resource.json
CTX_RES_UUID = 'cc45b9b4-dbf6-47b3-40ac-08debc0cec5b'

nodes = [
    {
        "id": "start",
        "type": "core.trigger.manual",
        "typeVersion": "1.0",
        "display": {"label": "Manual trigger"},
        "inputs": {
            "entryPointId": flow['nodes'][0]['inputs']['entryPointId'],
            "isDefaultEntryPoint": True
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "The return value of the trigger.",
                "source": "=result.response",
                "var": "output"
            }
        }
    },
    # Step 1: IxP extraction
    {
        "id": "extractInvoice",
        "type": "uipath.ixp.invoices-billing-f0c606f9-ixp.99f5bbfa-5f29-8033-8662-25001b6bb18e-79a7d12e-da84-4bf4-ab60-7f34b44dd178",
        "typeVersion": "1.0.0",
        "display": {"label": "Invoice Extraction (IxP)"},
        "inputs": {
            "model": ixp_model_blob,
            "modelName": ixp_defaults.get('modelName', 'invoices-billing-f0c606f9-ixp'),
            "projectName": ixp_defaults.get('projectName', 'invoices-billing-f0c606f9-ixp'),
            "folderKey": ixp_defaults.get('folderKey', '79a7d12e-da84-4bf4-ab60-7f34b44dd178'),
            "folderName": ixp_defaults.get('folderName', 'Shared/uipath-maestro-flow/BillingDispute'),
            "versionTag": "",
            "pageRange": "",
            "fileRef": "=js:$vars.start.output.disputedInvoice"
        },
        "outputs": {
            "output": ixp_out['output'],
            "error": ixp_out['error']
        }
    },
    # Step 2: Normalize Data script
    {
        "id": "normalizeData",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Normalize Data"},
        "inputs": {
            "script": """const fields = ($vars.extractInvoice.output.ExtractionResult || {}).ResultsDocument
  ? $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields || []
  : [];
const normalized = fields.map(function(f) {
  return {
    Id: f.FieldId,
    Name: f.FieldName,
    Value: (f.Values && f.Values.length > 0) ? f.Values[0] : null,
    Type: f.FieldType,
    IsMissing: f.IsMissing,
    Confidence: f.Confidence
  };
});
return { fields: normalized };"""
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "Normalized IxP fields",
                "source": "=result.response",
                "var": "output"
            },
            "error": {
                "type": "object",
                "description": "Error information",
                "source": "=result.Error",
                "var": "error"
            }
        }
    },
    # CRM Lookup (already in flow as crmLookup1)
    {
        "id": "crmLookup1",
        "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
        "typeVersion": "1.0.0",
        "display": {"label": "CRM Lookup"}
    },
    # ERP Lookup (already in flow as erpLookup1)
    {
        "id": "erpLookup1",
        "type": "uipath.connector.uipath-uipath-dataservice.query-entity-records",
        "typeVersion": "1.0.0",
        "display": {"label": "ERP Lookup"}
    },
    # Step 4: Merge
    {
        "id": "mergeResults",
        "type": "core.logic.merge",
        "typeVersion": "1.0",
        "display": {"label": "Merge CRM + ERP"},
        "inputs": {},
        "outputs": {
            "output": {
                "type": "object",
                "description": "Merged parallel branch outputs",
                "source": "=result.response",
                "var": "output"
            }
        }
    },
    # Step 5: Discrepancy Detection
    {
        "id": "discrepancyDetection",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Discrepancy Detection"},
        "inputs": {
            "script": """const disputedItems = ($vars.start.output.webhookPayload || {}).dispute
  ? ($vars.start.output.webhookPayload.dispute.disputedLineItems || [])
  : [];
const erpRecords = ($vars.erpLookup1.output && $vars.erpLookup1.output.value) || [];
const mismatches = [];
let totalOvercharge = 0;
let totalUndercharge = 0;
disputedItems.forEach(function(item) {
  const contract = erpRecords.find(function(r) { return r.lineNumber === item.lineNumber; });
  if (contract) {
    const diff = (item.amount || 0) - (contract.contractAmount || contract.amount || 0);
    if (diff !== 0) {
      mismatches.push({
        lineNumber: item.lineNumber,
        description: item.description,
        disputedAmount: item.amount,
        contractAmount: contract.contractAmount || contract.amount,
        difference: diff
      });
      if (diff > 0) {
        totalOvercharge += diff;
      } else {
        totalUndercharge += Math.abs(diff);
      }
    }
  }
});
return {
  mismatches: mismatches,
  totalOvercharge: totalOvercharge,
  totalUndercharge: totalUndercharge,
  mismatchCount: mismatches.length
};"""
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "Discrepancy analysis results",
                "source": "=result.response",
                "var": "output"
            },
            "error": {
                "type": "object",
                "description": "Error information",
                "source": "=result.Error",
                "var": "error"
            }
        }
    },
    # Step 6: Dispute Analyst Agent
    {
        "id": "disputeAnalyst",
        "type": "uipath.agent.autonomous",
        "typeVersion": "1.2",
        "display": {"label": "Dispute Analyst Agent"},
        "inputs": {
            "systemPrompt": "You are a billing dispute analyst. Analyze invoice disputes and return a structured determination.",
            "userPrompt": "Analyze the billing dispute and return determination, recommendedAction, autoResolutionEligible, creditAmount, confidence, and rationale.",
            "source": ANALYST_ID,
            "agentInputVariables": [
                {"id": "start__output__webhookPayload", "type": "object", "binding": "=$vars.start.output.webhookPayload", "description": "Webhook payload with dispute details"},
                {"id": "normalizeData__output__fields", "type": "array", "binding": "=$vars.normalizeData.output.fields", "description": "Normalized IxP fields"},
                {"id": "crmLookup1__output__value", "type": "object", "binding": "=$vars.crmLookup1.output", "description": "CRM customer records"},
                {"id": "erpLookup1__output__value", "type": "object", "binding": "=$vars.erpLookup1.output", "description": "ERP invoice records"},
                {"id": "discrepancyDetection__output__mismatches", "type": "array", "binding": "=$vars.discrepancyDetection.output.mismatches", "description": "Detected discrepancies"},
                {"id": "discrepancyDetection__output__totalOvercharge", "type": "number", "binding": "=$vars.discrepancyDetection.output.totalOvercharge", "description": "Total overcharge amount"},
                {"id": "discrepancyDetection__output__totalUndercharge", "type": "number", "binding": "=$vars.discrepancyDetection.output.totalUndercharge", "description": "Total undercharge amount"}
            ],
            "agentOutputVariables": [
                {"id": "determination", "type": "string"},
                {"id": "recommendedAction", "type": "string"},
                {"id": "autoResolutionEligible", "type": "boolean"},
                {"id": "creditAmount", "type": "number"},
                {"id": "confidence", "type": "number"},
                {"id": "rationale", "type": "string"}
            ]
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "Agent response",
                "source": "=result.response",
                "var": "output"
            },
            "error": {
                "type": "object",
                "description": "Error information if the node fails",
                "source": "=Error",
                "var": "error"
            }
        }
    },
    # Billing Dispute SOP Index context resource node
    {
        "id": "billingDisputeSopIndex",
        "type": "uipath.agent.resource.context.index.billing-dispute-sop-index.cc45b9b4-dbf6-47b3-40ac-08debc0cec5b",
        "typeVersion": "1.0.0",
        "display": {"label": "Billing Dispute SOP Index"},
        "inputs": {"source": CTX_RES_UUID}
    },
    # Step 7: Switch on recommendedAction
    {
        "id": "switchAction",
        "type": "core.logic.switch",
        "typeVersion": "1.1",
        "display": {"label": "Switch on Recommended Action"},
        "inputs": {
            "cases": [
                {"id": "escalate", "label": "Escalate to Manager", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'escalate_to_manager'"},
                {"id": "autoResolve", "label": "Auto Resolve", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'auto_resolve'"},
                {"id": "reject", "label": "Reject", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'reject'"}
            ]
        }
    },
    # Step 8: Approval Decision (manager approval - default Approved)
    {
        "id": "approvalDecision",
        "type": "core.logic.decision",
        "typeVersion": "1.1",
        "display": {"label": "Manager Approval"},
        "inputs": {
            "expression": "false",
            "trueLabel": "Rejected",
            "falseLabel": "Approved"
        }
    },
    # Log Credit Amount script (on auto_resolve path before financial posting)
    {
        "id": "logCreditAmount",
        "type": "core.action.script",
        "typeVersion": "1.0",
