        "inputs": {
            "script": "return { creditAmount: $vars.disputeAnalyst.output.creditAmount };"
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "Credit amount",
                "source": "=result.response",
                "var": "output"
            },
            "error": {
                "type": "object",
                "description": "Error information",
                "source": "=result.Error",
                "var": "error"
            }
        }
    },
    # Step 9a: Financial Posting (API Workflow)
